import { sendFeedback } from '../api/feedback.js';
import { getConfigCredentials } from './accountCredentials.js';
import { pkg } from './jsonLoader.js';
export function containsAccountCredentials(feedback) {
    return getConfigCredentials().some(credential => feedback.includes(credential));
}
export async function submitFeedback(accountId, feedback, source) {
    await sendFeedback(accountId, {
        feedback,
        source,
        cliVersion: pkg.version,
    });
}
